{
  "name": "@ekworp/opencode-mystatus",
  "version": "1.2.11",
  "description": "Check all your AI subscription quotas in one command. Supports OpenAI, Zhipu AI, Z.ai, and Google Antigravity. More platforms coming soon.",
  "type": "module",
  "main": "dist/plugin/mystatus.js",
  "types": "dist/plugin/mystatus.d.ts",
  "exports": {
    ".": {
      "import": "./dist/plugin/mystatus.js",
      "types": "./dist/plugin/mystatus.d.ts"
    }
  },
  "files": [
    "dist",
    "command",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc",
    "test": "pnpm build && node --loader ./tests/extension-loader.mjs --test tests/*.test.js",
    "typecheck": "tsc --noEmit",
    "lint": "biome check .",
    "lint:fix": "biome check --write .",
    "format": "biome format --write .",
    "prepublishOnly": "pnpm run lint && pnpm run build",
    "publish:npm": "npm publish --access public --registry=https://registry.npmjs.org",
    "prepare": "husky"
  },
  "keywords": [
    "opencode",
    "plugin",
    "quota",
    "status",
    "openai",
    "zhipu",
    "zai",
    "google",
    "antigravity",
    "gemini",
    "claude"
  ],
  "author": "javazys",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/ekworp/opencode-mystatus.git"
  },
  "bugs": {
    "url": "https://github.com/ekworp/opencode-mystatus/issues"
  },
  "homepage": "https://github.com/ekworp/opencode-mystatus#readme",
  "dependencies": {
    "@opencode/plugin": "2.0.25",
    "undici": "^6.29.0"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.5.15",
    "@types/node": "^22.0.0",
    "husky": "^9.1.7",
    "typescript": "^5.8.0"
  },
  "peerDependencies": {
    "@opencode/plugin": "2.0.25"
  },
  "engines": {
    "node": ">=18.0.0"
  }
}
